const viewer=shell('PGDCN · Sơ đồ Archify','<main class="wrap"><div class="eyebrow">PGDCN · Viewer offline</div><div class="actions"><a class="tag" href="index.html">← Atlas</a><a class="tag" id="handbook" href="node-handbook.html">Sổ tay node</a><a class="tag" href="document-matrix-pcn.html">Bảng hồ sơ PCN</a><a class="tag" href="document-matrix-pgd.html">Bảng hồ sơ PGD</a></div><h1 id="title">Sơ đồ</h1><p id="summary" class="muted">Mở sơ đồ static Archify bằng file://; không gọi API.</p><section class="two"><aside class="card"><h2>Ba sơ đồ chính</h2><nav id="primary" class="list" aria-label="Ba sơ đồ chính"></nav><h2>Sơ đồ liên quan</h2><nav id="related" class="list" aria-label="Sơ đồ cùng domain"></nav></aside><iframe id="frame" class="mapframe" title="Sơ đồ Archify" loading="eager"></iframe></section></main>','const d='+q(diagramIndex)+';const e='+q(entries)+';const $=x=>document.querySelector(x);function esc(x){return String(x??"").replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\\\"":"&quot;"}[c]))}const key=new URLSearchParams(location.search).get("map");const m=d.find(x=>x.file===key||x.id===key);if(!m){$("#title").textContent="Không tìm thấy sơ đồ";$("#summary").textContent="Trở về Atlas và chọn một map trong danh mục."}else{$("#title").textContent=m.title;document.title=m.title+" · PGDCN";$("#summary").textContent=(m.domain||"")+" · "+(m.group||"")+" · "+(m.templateId||m.workflowId||"")+" · "+(m.templateStatus||m.workflowStatus||"");$("#frame").src=m.file;const n=e.find(x=>x.mapId===m.id);if(n)$("#handbook").href="node-handbook.html#node="+encodeURIComponent(n.id);function links(sel,items){$(sel).innerHTML=items.map(x=>"<a href=\\\"diagram-viewer.html?map="+encodeURIComponent(x.file)+"\\\">"+esc(x.title)+"</a>").join("")}links("#primary",d.filter(x=>x.primary));links("#related",d.filter(x=>x.id!==m.id&&(x.primary||(x.domain===m.domain&&x.group!=="technical"))))}');
