const index=shell('PGDCN Archify · Final Delivery','<main class="wrap"><div class="eyebrow">PGDCN · ARCHIFY · '+REV+'</div><h1>Atlas vận hành & hồ sơ PGDCN</h1><p class="muted">Ba sơ đồ chính trước; bên dưới là từng profile hồ sơ cụ thể; cuối trang là sơ đồ kỹ thuật tham chiếu. Các file là static HTML dùng relative links, không cần mạng/API và không chứa case/customer data.</p><div class="actions"><a class="tag" href="node-handbook.html">Sổ tay node có tìm kiếm</a><a class="tag" href="document-matrix-pcn.html">Bảng file PCN</a><a class="tag" href="document-matrix-pgd.html">Bảng file PGD</a><a class="tag" href="README.md">README</a></div><h2>Ba sơ đồ chính</h2><section class="grid" style="grid-template-columns:repeat(auto-fit,minmax(290px,1fr))">'+pLinks+'</section><h2>Áp dụng theo bộ hồ sơ cụ thể</h2><p class="muted">13 map: hai PCN blank dossier pack trong code và toàn bộ 11 active PGD code-catalog profiles. Catalog profile không bị trình bày thành workflow PUBLISHED record. Runtime workflow ID/version/status là NOT_VERIFIED.</p><div class="toolbar"><input id="q" type="search" placeholder="Tìm tên/mã, workflow ID, node, role, tệp…"><select id="domain"><option value="">PCN + PGD</option><option>PCN</option><option>PGD</option></select><button id="clear">Xóa lọc</button><span id="count"></span></div><div class="grid" id="variants" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))">'+vLinks+'</div><h2>Tham chiếu kỹ thuật</h2><div class="grid" id="technical" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))">'+tLinks+'</div><p class="muted">Bằng chứng: <a href="source-evidence-final.md">source-evidence-final.md</a> · <a href="coverage-matrix.md">coverage-matrix.md</a> · <a href="node-playbook.json">node-playbook.json</a></p></main>','const d='+q(searchIndex)+';const a=[...document.querySelectorAll(".variant,.tech")],qel=document.querySelector("#q"),dom=document.querySelector("#domain"),count=document.querySelector("#count");function go(){let t=qel.value.toLowerCase(),n=0;for(const c of a){let m=d.find(x=>x.id===c.dataset.map),ok=(!dom.value||m.domain===dom.value||m.domain==="Tham chiếu")&&(!t||m.searchText.toLowerCase().includes(t));c.classList.toggle("hidden",!ok);if(ok)n++}count.textContent=n+" kết quả"}qel.oninput=go;dom.onchange=go;document.querySelector("#clear").onclick=()=>{qel.value="";dom.value="";go()};go()');
